// Justified-row layout engine for the photo gallery (pure, DOM-free).
//
// Faithful port of the original Python `compute_justified_layout`: photos keep their aspect
// ratio, every row except the last is scaled to fill the width exactly, and `density` is the
// *target* number of photos per row. tests/layout.test.mjs checks it against fixtures that
// were generated by the Python implementation.

export const DEFAULT_ASPECT = 1.5;

// Python's round() is "banker's rounding"; Math.round() is not. Match Python exactly.
export function pyRound(x) {
  const f = Math.floor(x);
  const d = x - f;
  if (d < 0.5) return f;
  if (d > 0.5) return f + 1;
  return f % 2 === 0 ? f : f + 1;
}

// Python >= 3.12 sums floats with Neumaier compensation; do the same for bit-identical rows.
function psum(arr, a, b) {
  let s = 0, c = 0;
  for (let i = a; i < b; i++) {
    const x = arr[i];
    const t = s + x;
    if (Math.abs(s) >= Math.abs(x)) c += (s - t) + x; else c += (x - t) + s;
    s = t;
  }
  return s + c;
}

export function computeJustifiedLayout(aspects, width, density, gap = 4) {
  width = Math.max(Math.trunc(width), 1);
  density = Math.max(Math.trunc(density), 1);
  const n = aspects.length;
  if (n === 0) return { tiles: [], rows: [], totalHeight: 0, width };

  const safe = aspects.map((a) => (a && a > 0.05 ? a : DEFAULT_ASPECT));
  const mean = psum(safe, 0, n) / n;
  const targetH = Math.max(8.0, (width - gap * (density - 1)) / density / mean);
  const fitHeight = (first, last) => (width - gap * (last - first - 1)) / psum(safe, first, last);

  // 1. partition into rows (greedy, choosing the split closest to targetH)
  const spans = [];
  let start = 0, i = 0;
  while (i < n) {
    i += 1;
    const count = i - start;
    const natural = psum(safe, start, i) * targetH + gap * (count - 1);
    if (natural >= width) {
      const hWith = fitHeight(start, i);
      if (count > 1) {
        const hWithout = fitHeight(start, i - 1);
        if (Math.abs(hWithout - targetH) < Math.abs(hWith - targetH)) i -= 1;
      }
      spans.push([start, i]);
      start = i;
    }
  }
  if (start < n) spans.push([start, n]);

  // 2. convert spans to pixel rectangles
  const tiles = [], rows = [];
  let y = 0;
  spans.forEach(([a, b], ri) => {
    const isLast = ri === spans.length - 1;
    const hFit = fitHeight(a, b);
    let rowH, justify;
    if (isLast && hFit > targetH) { rowH = pyRound(targetH); justify = false; }
    else { rowH = pyRound(hFit); justify = true; }
    rowH = Math.max(rowH, 4);

    const firstTile = tiles.length;
    let x = 0;
    for (let slot = a; slot < b; slot++) {
      const w = justify && slot === b - 1
        ? Math.max(width - x, 2)                       // absorb rounding error -> flush edge
        : Math.max(pyRound(safe[slot] * rowH), 2);
      tiles.push({ slot, x, y, w, h: rowH });
      x += w + gap;
    }
    rows.push({ y, h: rowH, first: firstTile, last: tiles.length });
    y += rowH + gap;
  });
  return { tiles, rows, totalHeight: Math.max(y - gap, 0), width };
}

// bisect_right on row.y
function bisectRight(rows, v) {
  let lo = 0, hi = rows.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (v < rows[mid].y) hi = mid; else lo = mid + 1;
  }
  return lo;
}

// (firstRow, lastRowExclusive) of rows intersecting [top, bottom]
export function rowsInRange(layout, top, bottom) {
  const { rows } = layout;
  if (!rows.length) return [0, 0];
  let first = Math.max(0, bisectRight(rows, top) - 1);
  while (first < rows.length && rows[first].y + rows[first].h < top) first++;
  const last = bisectRight(rows, bottom);
  return [first, Math.max(first, last)];
}
